let lang = (() => { try { return localStorage.getItem('banda_lang') || 'en'; } catch (e) { return 'en'; } })();
export const getLang = () => lang;
export function setLang(l) { lang = D[l] ? l : 'en'; try { localStorage.setItem('banda_lang', lang); sessionStorage.setItem('banda_lang_chosen', '1'); } catch (e) {} }
export function langChosen() { try { return !!sessionStorage.getItem('banda_lang_chosen'); } catch (e) { return false; } }
export function t(k) { return D[lang][k] ?? D.en[k] ?? k; }
export function applyI18n() {
  document.documentElement.lang = lang;
  document.title = t('title');
  document.querySelectorAll('[data-i18n]').forEach(e => { e.textContent = t(e.dataset.i18n); });
  document.querySelectorAll('[data-i18n-ph]').forEach(e => { e.placeholder = t(e.dataset.i18nPh); });
  document.querySelectorAll('[data-i18n-html]').forEach(e => { e.innerHTML = t(e.dataset.i18nHtml); });
  document.querySelectorAll('[data-i18n-title]').forEach(e => { e.title = t(e.dataset.i18nTitle); e.setAttribute('aria-label', e.title); });
}
